using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Payments.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Payments.Queries.GetPaymentById;public sealed class GetPaymentByIdQueryHandler(IPaymentRepository repository):IRequestHandler<GetPaymentByIdQuery,Result<PaymentDto>>{public async Task<Result<PaymentDto>>Handle(GetPaymentByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<PaymentDto>(PaymentErrors.NotFound):Result.Success(PaymentDto.FromEntity(e));}}
